"""Plot the H II region diagnostics generated by make -C test hii."""

import argparse
from pathlib import Path

import matplotlib

if __name__ == "__main__":
    matplotlib.use("Agg")

import matplotlib.pyplot as plt
from matplotlib.ticker import FixedLocator, ScalarFormatter
import numpy as np

from plot_style import BLUE, GRAY, GREEN, ORANGE, PLOT_STYLE, PURPLE


PLOT_DIR = Path(__file__).resolve().parent
ION_COLORS = (GRAY, BLUE, ORANGE)
RATE_LABEL = r"Rate / $n_{\rm H}^2$ [erg cm$^3$ s$^{-1}$]"
ELEMENTS = {
    "Hydrogen": ("HI", "HII"),
    "Helium": ("HeI", "HeII", "HeIII"),
    "Carbon": ("CI", "CII", "CIII"),
    "Oxygen": ("OI", "OII", "OIII"),
    "Silicon": ("SiI", "SiII", "SiIII"),
}
ION_LABELS = {
    f"{element}{stage}": f"{element} {stage}"
    for element in ("H", "He", "C", "O", "Si")
    for stage in ("I", "II", "III")
}


def load_csv(path):
    data = np.genfromtxt(path, names=True, delimiter=",", dtype=None, encoding="utf-8", ndmin=1)
    if not data.size:
        raise ValueError(f"No data in {path}")
    return data


def load_results(data_dir):
    equilibrium = load_csv(data_dir / "equilibrium.csv")
    thermal = np.sort(load_csv(data_dir / "thermal_curve.csv"), order="T")
    reactions = load_csv(data_dir / "reactions.csv")

    sample = thermal[0]
    selected = equilibrium[(equilibrium["nH"] == sample["nH"])
                           & (equilibrium["Z_solar"] == sample["Z_solar"])
                           & (equilibrium["log_U"] == sample["log_U"])]
    if len(selected) != 1:
        raise ValueError("The temperature scan needs one matching row in equilibrium.csv")
    return equilibrium, thermal, reactions[reactions["sample"] == "thermal_curve"], selected[0]


def plot_equilibrium(data, nH):
    fig, axes = plt.subplots(2, 3, figsize=(11, 6), sharex=True, layout="constrained")
    fig.suptitle(rf"H II region equilibrium · $n_{{\rm H}}={nH:g}$ cm$^{{-3}}$")
    at_density = data[data["nH"] == nH]
    log_u = np.unique(at_density["log_U"])

    ax = axes[0, 0]
    for metallicity, color in zip((0.0, 0.1, 1.0), ("#555555", ORANGE, BLUE)):
        grid = data[data["Z_solar"] == metallicity]
        selected = at_density[at_density["Z_solar"] == metallicity]
        selected = np.sort(selected, order="log_U")
        columns = [grid["T"][grid["log_U"] == u] / 1e3 for u in log_u]
        ax.fill_between(log_u, [col.min() for col in columns], [col.max() for col in columns],
                        color=color, alpha=0.16, linewidth=0)
        ax.plot(selected["log_U"], selected["T"] / 1e3, "o-", color=color, ms=3,
                label=rf"$Z/Z_\odot = {metallicity:g}$")
    ax.set(title="Temperature", ylabel=r"$T_{\rm eq}$ [$10^3$ K]")
    ax.legend(loc="upper left")
    ax.text(0.97, 0.28, r"Bands span $n_{\rm H}=1$–$10^3$ cm$^{-3}$",
            transform=ax.transAxes, ha="right", fontsize=8)

    reference = np.sort(at_density[at_density["Z_solar"] == 1], order="log_U")
    dilute = np.sort(at_density[at_density["Z_solar"] == 0.1], order="log_U")
    legend_positions = ("lower left", "center left", "upper center", "upper center", "upper center")
    for ax, (element, ions), position in zip(axes.flat[1:], ELEMENTS.items(), legend_positions):
        for ion, color in zip(ions, ION_COLORS):
            ax.plot(reference["log_U"], reference[ion], color=color, label=ION_LABELS[ion])
            if element not in ("Hydrogen", "Helium"):
                ax.plot(dilute["log_U"], dilute[ion], color=color, ls="--")
        ax.set(title=element, ylim=(-0.03, 1.06))
        ax.legend(loc=position, fontsize=8, ncol=1 if element in ("Hydrogen", "Helium") else 3)
    axes[0, 1].set(yscale="log", ylim=(1e-4, 1.5), ylabel="Ion fraction")
    axes[1, 0].set_ylabel("Ion fraction")
    for ax in axes[-1]:
        ax.set_xlabel(r"$\log_{10} U$    ($U=\Phi_{\rm LyC}/n_{\rm H}c$)")
    fig.supxlabel(r"Ion fractions at $Z/Z_\odot=1$ (solid) and $0.1$ (dashed, C/O/Si)", fontsize=9)
    return fig


def temperature_axis(ax):
    ax.set(xscale="log", xlim=(10**0.5, 10**1.5), xlabel=r"Gas temperature [$10^3$ K]")
    ax.xaxis.set_major_locator(FixedLocator([4, 6, 10, 20, 30]))
    ax.xaxis.set_major_formatter(ScalarFormatter())


def condition_label(row):
    return (rf"$n_{{\rm H}}={row['nH']:g}$ cm$^{{-3}}$, "
            rf"$Z/Z_\odot={row['Z_solar']:g}$, $\log_{{10}} U={row['log_U']:g}$")


def plot_thermal(data, equilibrium):
    sample = data[0]
    teq = equilibrium["T"] / 1e3
    temperature = data["T"] / 1e3
    density_squared = data["nH"]**2

    fig = plt.figure(figsize=(11, 6.5), layout="constrained")
    grid = fig.add_gridspec(2, 2, height_ratios=(2.3, 1))
    heating, cooling = fig.add_subplot(grid[0, 0]), fig.add_subplot(grid[0, 1])
    net = fig.add_subplot(grid[1, :])
    fig.suptitle("H II region thermal balance · " + condition_label(sample))
    heating_terms = (
        ("Total heating", data["H_tot"], "#202020", "-"),
        ("H photoionization", data["H_PI_H"], BLUE, "-"),
        ("He photoionization", data["H_PI_He"], ORANGE, "-"),
        ("Metal photoionization", data["H_PI_metals"], GREEN, "-"),
    )
    cooling_terms = (
        ("Total cooling", data["L_tot"], "#202020", "-"),
        ("[O II]", data["L_OII"], BLUE, "-"),
        ("[O III]", data["L_OIII"], ORANGE, "-"),
        ("H and He", data["L_HI"] + data["L_HeI"] + data["L_HeII"], GREEN, "-"),
        ("Free-free", data["L_ff"], PURPLE, "-"),
        ("CIE metals", data["L_res"], "#555555", "--"),
    )
    for ax, terms, title in ((heating, heating_terms, "Heating"), (cooling, cooling_terms, "Cooling")):
        for label, rate, color, style in terms:
            ax.plot(temperature, np.ma.masked_less_equal(rate / density_squared, 0),
                    color=color, ls=style, lw=2 if label.startswith("Total") else 1.45, label=label)
        ax.set(title=title, yscale="log", ylim=(1e-26, 3e-22), ylabel=RATE_LABEL)
        ax.legend(loc="upper left", ncol=2, fontsize=8)
        ax.axvline(teq, color="#777777", ls=":")
        temperature_axis(ax)

    normalized_net = data["net_heating"] / (data["H_tot"] + data["L_tot"])
    net.axhline(0, color="#555555", lw=0.8)
    net.axvline(teq, color="#777777", ls=":", label=rf"$T_{{\rm eq}}={teq*1000:,.0f}$ K")
    net.plot(temperature, normalized_net, color="#202020")
    net.fill_between(temperature, 0, normalized_net.clip(min=0), color=ORANGE, alpha=0.18, label="Net heating")
    net.fill_between(temperature, 0, normalized_net.clip(max=0), color=BLUE, alpha=0.18, label="Net cooling")
    net.set(ylim=(-1.08, 1.08), ylabel=r"$(H-L)/(H+L)$")
    net.legend(loc="upper right", ncol=3, fontsize=8)
    temperature_axis(net)
    return fig


def plot_reactions(data, equilibrium):
    fig, axes = plt.subplots(3, 3, figsize=(11, 8), sharex=True, layout="constrained")
    fig.suptitle("H II region reaction rates · " + condition_label(data[0]))
    for ax, ion in zip(axes.flat, ("HI", "HeI", "HeII", "CI", "CII", "OI", "OII", "SiI", "SiII")):
        rows = np.sort(data[data["ion"] == ion], order="T")
        density_squared = rows["nH"]**2
        upper_ion = ION_LABELS[ion] + "I"
        for field, label, color, style in (
            ("recombination", "Electron recombination", "#555555", "-"),
            ("photoionization", "Photoionization", BLUE, "--"),
            ("collisional_ionization", "Electron-impact ionization", ORANGE, "-"),
        ):
            rate = np.ma.masked_less_equal(rows[field] / density_squared, 0)
            ax.plot(rows["T"] / 1e3, rate, color=color, ls=style, label=label)
        peak = np.max(rows["recombination"] / density_squared)
        ax.set(title=f"{ION_LABELS[ion]} ↔ {upper_ion}", yscale="log", ylim=(peak*1e-6, peak*3))
        ax.axvline(equilibrium["T"] / 1e3, color="#777777", ls=":", label=r"$T_{\rm eq}$")
        temperature_axis(ax)
    for ax in axes[:-1].flat:
        ax.set_xlabel("")
    fig.supylabel(r"Reactions / $n_{\rm H}^2$ [cm$^3$ s$^{-1}$]", fontsize=10)
    handles, labels = axes[0, 0].get_legend_handles_labels()
    fig.legend(handles, labels, loc="outside lower center", ncol=len(labels))
    return fig


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data-dir", type=Path, default=PLOT_DIR.parent / "test" / "out" / "hii")
    parser.add_argument("--output-dir", type=Path, default=PLOT_DIR / "out" / "hii")
    args = parser.parse_args()
    try:
        equilibrium, thermal, reactions, reference = load_results(args.data_dir)
    except (OSError, ValueError) as error:
        parser.error(str(error))

    args.output_dir.mkdir(parents=True, exist_ok=True)
    with plt.rc_context(PLOT_STYLE):
        figures = {
            "equilibrium.png": plot_equilibrium(equilibrium, reference["nH"]),
            "thermal_balance.png": plot_thermal(thermal, reference),
            "reaction_rates.png": plot_reactions(reactions, reference),
        }
        for name, fig in figures.items():
            fig.savefig(args.output_dir / name, dpi=180)
            plt.close(fig)
    print(f"H II region plots written to {args.output_dir}")


if __name__ == "__main__":
    main()
